import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"Security, Anti-Spam & Fraud Prevention","description":"","frontmatter":{},"headers":[],"relativePath":"admin/security.md","filePath":"admin/security.md","lastUpdated":null}'),o={name:"admin/security.md"};function s(r,e,l,c,d,u){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="security-anti-spam-fraud-prevention" tabindex="-1">Security, Anti-Spam &amp; Fraud Prevention <a class="header-anchor" href="#security-anti-spam-fraud-prevention" aria-label="Permalink to &quot;Security, Anti-Spam &amp; Fraud Prevention&quot;">​</a></h1><p>FOSSBilling is hardened against abuse, fraudulent orders, brute-force attacks, and cross-site scripting (XSS).</p><hr><h2 id="🛡️-active-security-modules" tabindex="-1">🛡️ Active Security Modules <a class="header-anchor" href="#🛡️-active-security-modules" aria-label="Permalink to &quot;🛡️ Active Security Modules&quot;">​</a></h2><h3 id="_1-disposable-email-address-detection" tabindex="-1">1. Disposable Email Address Detection <a class="header-anchor" href="#_1-disposable-email-address-detection" aria-label="Permalink to &quot;1. Disposable Email Address Detection&quot;">​</a></h3><ul><li>Validates client registration against a continuously updated blacklist of 1,000+ temporary/throwaway email domains (<code>pkg/security/disposable_email.go</code>).</li><li>Blocks throwaway accounts while allowing legitimate personal and corporate emails.</li></ul><h3 id="_2-ip-blocklist-honeypot-protection" tabindex="-1">2. IP Blocklist &amp; Honeypot Protection <a class="header-anchor" href="#_2-ip-blocklist-honeypot-protection" aria-label="Permalink to &quot;2. IP Blocklist &amp; Honeypot Protection&quot;">​</a></h3><ul><li><strong>Honeypot Form Fields:</strong> Invisible hidden fields catch automated spam bots attempting registration or contact submissions.</li><li><strong>StopForumSpam Integration:</strong> Cross-references client IP and email against global abuse databases.</li><li><strong>CIDR Blocklist:</strong> Manual and automatic IP subnet blocking.</li></ul><h3 id="_3-sha-256-client-fingerprinting" tabindex="-1">3. SHA-256 Client Fingerprinting <a class="header-anchor" href="#_3-sha-256-client-fingerprinting" aria-label="Permalink to &quot;3. SHA-256 Client Fingerprinting&quot;">​</a></h3><ul><li>Generates a deterministic device/session fingerprint based on User-Agent, Accept headers, encoding preferences, and IP address (<code>pkg/security/fingerprint.go</code>).</li><li>Detects credential stuffing and session hijacking attempts.</li></ul><h3 id="_4-input-sanitization-anti-xss" tabindex="-1">4. Input Sanitization &amp; Anti-XSS <a class="header-anchor" href="#_4-input-sanitization-anti-xss" aria-label="Permalink to &quot;4. Input Sanitization &amp; Anti-XSS&quot;">​</a></h3><ul><li>All incoming HTML and text inputs are sanitized with anti-XSS stripping rules (<code>pkg/security/sanitizer.go</code>).</li></ul><h3 id="_5-audit-logging-role-based-access-control-rbac" tabindex="-1">5. Audit Logging &amp; Role-Based Access Control (RBAC) <a class="header-anchor" href="#_5-audit-logging-role-based-access-control-rbac" aria-label="Permalink to &quot;5. Audit Logging &amp; Role-Based Access Control (RBAC)&quot;">​</a></h3><ul><li>All staff administrative actions (client updates, server reboots, invoice edits, currency changes) are logged immutably in the <code>audit_logs</code> table.</li></ul>',14)])])}const g=a(o,[["render",s]]);export{m as __pageData,g as default};
